-- Synthetic schema-16 fixture from normal app commit b93ae193ed5c4316885aae6f661a11293516315b.
BEGIN TRANSACTION;
CREATE TABLE "app_settings" ("key" TEXT NOT NULL, "value" TEXT NOT NULL, PRIMARY KEY ("key"));
INSERT INTO "app_settings" VALUES('preferredDirection','targetToNative');
CREATE TABLE "category_dimensions" ("id" TEXT NOT NULL, "collection_id" TEXT NOT NULL REFERENCES collections (id) ON DELETE CASCADE, "name" TEXT NOT NULL, "name_key" TEXT NOT NULL, "mode" TEXT NOT NULL, "position" INTEGER NOT NULL, PRIMARY KEY ("id"), CHECK(length(trim(name)) > 0), CHECK(mode IN ('single', 'multiple')), CHECK(position >= 0), UNIQUE(collection_id, name_key), UNIQUE(id, collection_id));
CREATE TABLE "category_values" ("id" TEXT NOT NULL, "dimension_id" TEXT NOT NULL REFERENCES category_dimensions (id) ON DELETE CASCADE, "name" TEXT NOT NULL, "name_key" TEXT NOT NULL, "position" INTEGER NOT NULL, PRIMARY KEY ("id"), CHECK(length(trim(name)) > 0), CHECK(position >= 0), UNIQUE(dimension_id, name_key), UNIQUE(id, dimension_id));
CREATE TABLE "collections" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "target_language" TEXT NOT NULL, "native_language" TEXT NOT NULL, "automatic_hint_default" INTEGER NOT NULL DEFAULT 0 CHECK ("automatic_hint_default" IN (0, 1)), "hint_default_offer_handled" INTEGER NOT NULL DEFAULT 0 CHECK ("hint_default_offer_handled" IN (0, 1)), PRIMARY KEY ("id"));
INSERT INTO "collections" VALUES('85a351e2-793b-4244-bbf9-d806caa2ebce','Korean','ko','de',0,0);
CREATE TABLE "learning_identity_sequence" ("singleton" INTEGER NOT NULL, "next_id" INTEGER NOT NULL, PRIMARY KEY ("singleton"), CHECK(singleton = 1), CHECK(next_id > 0));
INSERT INTO "learning_identity_sequence" VALUES(1,3);
CREATE TABLE "learning_items" ("id" INTEGER NOT NULL, "entry_id" TEXT NOT NULL REFERENCES vocabulary_entries (id) ON DELETE CASCADE, "direction" TEXT NOT NULL, "format_version" INTEGER NOT NULL, "card_json" TEXT NOT NULL, "generation" INTEGER NOT NULL DEFAULT 0 CHECK(generation >= 0), "review_revision" INTEGER NOT NULL DEFAULT 0 CHECK(review_revision >= 0), "speed_completed" INTEGER NOT NULL DEFAULT 0 CHECK ("speed_completed" IN (0, 1)), PRIMARY KEY ("id"), CHECK(id > 0), CHECK(direction IN ('targetToNative', 'nativeToTarget')), CHECK(format_version = 1), UNIQUE(entry_id, direction));
INSERT INTO "learning_items" VALUES(1,'42b9e72c-eb03-4382-bdbb-d794d332682c','targetToNative',1,'{"cardId":1,"state":2,"step":null,"stability":3.2602,"difficulty":4.884631634813845,"due":"2026-10-21T03:08:31.473613Z","lastReview":"2026-10-18T03:08:31.473613Z"}',0,1,0);
INSERT INTO "learning_items" VALUES(2,'42b9e72c-eb03-4382-bdbb-d794d332682c','nativeToTarget',1,'{"cardId":2,"state":1,"step":0,"stability":null,"difficulty":null,"due":"2026-10-18T03:07:51.388931Z","lastReview":null}',0,0,0);
CREATE TABLE "regular_reviews" ("id" TEXT NOT NULL, "item_id" INTEGER NOT NULL REFERENCES learning_items (id) ON DELETE CASCADE, "generation" INTEGER NOT NULL, "reviewed_at" TEXT NOT NULL, "rating" TEXT NOT NULL, PRIMARY KEY ("id"), CHECK(length(id) > 0), CHECK(generation >= 0), CHECK(rating IN ('again', 'hard', 'good')), CHECK(substr(reviewed_at, -1) = 'Z'));
INSERT INTO "regular_reviews" VALUES('1fe6951f-7180-46ef-8dcb-c0261c0aa487',1,0,'2026-10-18T03:08:31.473613Z','good');
CREATE TABLE "retry_obligations" ("id" TEXT NOT NULL, "item_id" INTEGER NOT NULL REFERENCES learning_items (id) ON DELETE CASCADE, "generation" INTEGER NOT NULL, "revision" INTEGER NOT NULL DEFAULT 0, "origin_review_id" TEXT NOT NULL REFERENCES regular_reviews (id) ON DELETE CASCADE, "created_at" TEXT NOT NULL, "expires_at" TEXT NOT NULL, "wait_eligible_at" TEXT NULL CHECK(wait_eligible_at IS NULL OR substr(wait_eligible_at, -1) = 'Z'), "error_count" INTEGER NOT NULL DEFAULT 1 CHECK(error_count >= 1), "due_ordinal" INTEGER NOT NULL DEFAULT 20 CHECK(due_ordinal >= 0), PRIMARY KEY ("id"), CHECK(length(trim(id)) > 0), CHECK(generation >= 0), CHECK(revision >= 0), UNIQUE(item_id, generation), CHECK(substr(created_at, -1) = 'Z'), CHECK(substr(expires_at, -1) = 'Z'));
CREATE TABLE "scope_answer_ordinals" ("collection_id" TEXT NOT NULL REFERENCES collections (id) ON DELETE CASCADE, "direction" TEXT NOT NULL, "ordinal" INTEGER NOT NULL, "revision" INTEGER NOT NULL, PRIMARY KEY ("collection_id", "direction"), CHECK(direction IN ('targetToNative', 'nativeToTarget')), CHECK(ordinal >= 0), CHECK(revision >= 0));
INSERT INTO "scope_answer_ordinals" VALUES('85a351e2-793b-4244-bbf9-d806caa2ebce','targetToNative',1,1);
CREATE TABLE "vocabulary_category_assignments" ("entry_id" TEXT NOT NULL, "collection_id" TEXT NOT NULL, "dimension_id" TEXT NOT NULL, "value_id" TEXT NOT NULL, PRIMARY KEY ("entry_id", "value_id"), FOREIGN KEY(entry_id, collection_id) REFERENCES vocabulary_entries(id, collection_id) ON DELETE CASCADE, FOREIGN KEY(dimension_id, collection_id) REFERENCES category_dimensions(id, collection_id) ON DELETE CASCADE, FOREIGN KEY(value_id, dimension_id) REFERENCES category_values(id, dimension_id) ON DELETE CASCADE);
CREATE TABLE "vocabulary_entries" ("id" TEXT NOT NULL, "collection_id" TEXT NOT NULL REFERENCES collections (id) ON DELETE CASCADE, "target_text" TEXT NOT NULL, "native_text" TEXT NOT NULL, "target_key" TEXT NOT NULL, "native_key" TEXT NOT NULL, "active" INTEGER NOT NULL DEFAULT 1 CHECK ("active" IN (0, 1)), "example_target_text" TEXT NULL CHECK(example_target_text IS NULL OR length(example_target_text) BETWEEN 1 AND 1000), "example_native_text" TEXT NULL CHECK((example_target_text IS NULL AND example_native_text IS NULL) OR (example_target_text IS NOT NULL AND example_native_text IS NOT NULL AND length(example_native_text) BETWEEN 1 AND 1000)), "added_at" TEXT NULL, "hint_text" TEXT NULL CHECK(hint_text IS NULL OR length(hint_text) BETWEEN 1 AND 2000), "hint_visibility" TEXT NOT NULL DEFAULT 'always' CHECK(hint_visibility IN ('always', 'hidden')), PRIMARY KEY ("id"), CHECK(length(trim(target_text)) > 0), CHECK(length(trim(native_text)) > 0), UNIQUE(collection_id, target_key, native_key));
INSERT INTO "vocabulary_entries" VALUES('42b9e72c-eb03-4382-bdbb-d794d332682c','85a351e2-793b-4244-bbf9-d806caa2ebce','anchor-draft','Anker','anchor-draft','anker',1,NULL,NULL,'2026-10-18T03:07:51.363043Z',NULL,'hidden');
CREATE TABLE "vocabulary_examples" ("entry_id" TEXT NOT NULL REFERENCES vocabulary_entries (id) ON DELETE CASCADE, "position" INTEGER NOT NULL CHECK(position >= 0), "target_text" TEXT NOT NULL CHECK(length(target_text) BETWEEN 1 AND 1000), "native_text" TEXT NOT NULL CHECK(length(native_text) BETWEEN 1 AND 1000), PRIMARY KEY ("entry_id", "position"));
CREATE TABLE "vocabulary_order_sequence" ("singleton" INTEGER NOT NULL, "next_row_id" INTEGER NOT NULL, PRIMARY KEY ("singleton"), CHECK(singleton = 1), CHECK(next_row_id > 0));
INSERT INTO "vocabulary_order_sequence" VALUES(1,2);
CREATE UNIQUE INDEX vocabulary_entry_ownership ON vocabulary_entries (id, collection_id);
COMMIT;
PRAGMA user_version=16;
